import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let ch: conc.Channel<Int64> = conc.channel(1)
    let r1 = ch.tryReceive()
    ch.send(3)
    let r2 = ch.tryReceive()
    let _ = ch.close()
    let r3 = ch.tryReceive()
    let r4 = ch.trySend(1)
    match r1 {
        Received(_) => { io.println("r1rec") }
        _ => { io.println("r1empty") }
    }
    match r2 {
        Received(x) => {
            if x == 3 {
                io.println("r2three")
            } else {
                io.println("r2x")
            }
        }
        _ => { io.println("r2other") }
    }
    match r3 {
        Closed => { io.println("r3closed") }
        _ => { io.println("r3other") }
    }
    match r4 {
        Sent => { io.println("s4sent") }
        Full => { io.println("s4full") }
        Closed => { io.println("s4closed") }
    }
    return Ok(())
}
